--
-- Table structure for table `devices`
--

CREATE TABLE `devices` (
  `id` int(11) NOT NULL,
  `hardware_id` varchar(100) NOT NULL,
  `devices_id` varchar(50) DEFAULT NULL,
  `ssid` varchar(40) DEFAULT NULL,
  `rssi` varchar(11) DEFAULT NULL,
  `version` varchar(20) DEFAULT NULL,
  `status` enum('online','offline') NOT NULL DEFAULT 'offline',
  `last_sent` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

