--
-- Table structure for table `device_actions`
--

CREATE TABLE `device_actions` (
  `actionid` int(11) NOT NULL,
  `hardware_id` varchar(50) NOT NULL,
  `action` enum('update','changename','changeendpoint','changeinterval') NOT NULL,
  `value` text DEFAULT NULL,
  `additional` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`additional`)),
  `status` enum('pending','sent','completed','failed') NOT NULL DEFAULT 'pending',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `sent_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

-- --------------------------------------------------------

--
-- Table structure for table `heartbeats`
--

CREATE TABLE `heartbeats` (
  `id` int(11) NOT NULL,
  `devices_id` varchar(50) NOT NULL,
  `heartbeaton` datetime NOT NULL,
  `ipaddress` varchar(50) DEFAULT NULL,
  `useragent` varchar(100) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

